// Helper to safely open tab and ensure it loads
async function openTabSafely(url) {
  const res = await tool.tabs_create({ url });
  const tabId = res.details.tabId;
  await new Promise(r => setTimeout(r, 2000));
  try {
    await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });
  } catch (e) {
    console.log(`Wait for tab ${tabId} warning: ${e.message}`);
  }
  return tabId;
}

