const tabId = 103795220;

// Let's extract all schools and ranks from table
let schools = await browserjs(tabId, () => {
  const rows = Array.from(document.querySelectorAll('tr, [role="row"]'));
  const results = [];
  for (const r of rows) {
    const text = r.textContent.replace(/\s+/g, ' ').trim();
    const rankMatch = text.match(/#(\d+)\s+in\s+Best Business Schools/);
    const link = r.querySelector('a[href*="/best-graduate-schools/top-business-schools/"]');
    if (rankMatch && link) {
      results.push({
        rank: parseInt(rankMatch[1], 10),
        name: link.textContent.trim(),
        fullText: text
      });
    }
  }
  return results;
});

console.log("Found schools:", schools.length);
for (const s of schools) {
  console.log(`#${s.rank} ${s.name}`);
}

// If less than 20, let's click "Load More"
if (schools.length < 20) {
  console.log("Clicking load more...");
  await browserjs(tabId, () => {
    const btns = Array.from(document.querySelectorAll('button')).filter(b => b.textContent.includes('Load More'));
    if (btns.length) btns[0].click();
  });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 3000 });
}

