const tabId = 103795220;

// Let's click "Load More" button and inspect the next batch
const clickResult = await browserjs(tabId, () => {
  const btns = Array.from(document.querySelectorAll('button')).filter(b => b.textContent.toLowerCase().includes('load more'));
  if (btns.length > 0) {
    btns[0].scrollIntoView();
    btns[0].click();
    return "clicked load more";
  }
  return "no load more button";
});
console.log(clickResult);

await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 4000 });

// Now let's extract unique schools and ranks
const uniqueSchools = await browserjs(tabId, () => {
  const seen = new Set();
  const results = [];
  const rows = Array.from(document.querySelectorAll('tr, [role="row"], div[class*="Card-"]'));
  for (const r of rows) {
    const text = r.textContent.replace(/\s+/g, ' ').trim();
    const rankMatch = text.match(/#(\d+)\s+in\s+Best Business Schools/);
    const link = r.querySelector('a[href*="/best-graduate-schools/top-business-schools/"]');
    if (rankMatch && link) {
      const name = link.textContent.trim();
      if (!seen.has(name)) {
        seen.add(name);
        results.push({
          rank: parseInt(rankMatch[1], 10),
          name: name
        });
      }
    }
  }
  return results;
});

console.log("Unique schools found so far:", uniqueSchools.length);
console.log(JSON.stringify(uniqueSchools, null, 2));

