  console.log("Fellowship section:", fundText.slice(fellowshipIdx - 50, fellowshipIdx + 500));
} else {
  console.log("No 'fellowship' in fundText. Fund text length:", fundText.length);
  console.log("Fund text sample:", fundText.slice(0, 1000));
}

