// Load the complete 20 schools data
const data = JSON.parse((await read("tmp://mba_data.json")).text);
console.log(`Loaded ${data.length} schools from tmp://mba_data.json.`);

// Count total funding opportunities
let totalFundingOpportunities = 0;
data.forEach(s => {
  totalFundingOpportunities += s.fellowships ? s.fellowships.length : 0;
});
console.log(`Total funding opportunities: ${totalFundingOpportunities}`);

// 1. Generate CSV
// Headers: School Name, MBA Program Name, Application Deadline, GMAT/GRE Policy, Application Fee, Program Length, Admissions URL, Fellowship/Scholarship Name, Eligibility Criteria, Funding Amount, Funding URL
const csvRows = [
  [
    "School Name",
    "MBA Program Name",
    "Application Deadline",
    "GMAT/GRE Policy",
    "Application Fee",
    "Program Length",
    "Admissions Link",
    "Fellowship / Scholarship Name",
    "Eligibility Criteria",
    "Funding Amount",
    "Official Funding Page Link"
  ]
];

data.forEach(s => {
  s.fellowships.forEach(f => {
    csvRows.push([
      s.school,
      s.program,
      s.deadlines,
      s.testPolicy,
      s.applicationFee,
      s.programLength,
      s.admissionsUrl,
      f.name,
      f.eligibility,
      f.amount,
      f.url
    ]);
  });
});

function escapeCsv(val) {
  if (val == null) return '""';
  const str = String(val).replace(/"/g, '""');
  return `"${str}"`;
}

const csvContent = csvRows.map(row => row.map(escapeCsv).join(",")).join("\n");
await writeFile("Top MBA Programs and Fellowships.csv", csvContent, "text/csv");
console.log("Written Top MBA Programs and Fellowships.csv");

// Also save artifact
await tool.artifact({
  action: "write",
  path: "files/",
  filename: "Top_MBA_Programs_and_Fellowships.csv",
  content: csvContent,
  mime_type: "text/csv"
});
console.log("Saved CSV artifact.");

// 2. Generate comprehensive Markdown Document
let md = `# Top MBA Programs and Fellowships\n\n`;
md += `This research document details the **Top 20 Full-Time MBA Programs in the United States** (defensible consensus ranking based on U.S. News & World Report and Poets&Quants), capturing official admissions deadlines, test requirements, application fees, program lengths, admissions URLs, and official named fellowships/scholarships with verified eligibility and award amounts.\n\n`;
md += `---\n\n`;

data.forEach((s, idx) => {
  md += `## ${idx + 1}. ${s.school} — ${s.program}\n\n`;
  md += `- **Application Deadlines:** ${s.deadlines}\n`;
  md += `- **GMAT / GRE & Test Waiver Policy:** ${s.testPolicy}\n`;
  md += `- **Application Fee:** ${s.applicationFee}\n`;
  md += `- **Program Length:** ${s.programLength}\n`;
  md += `- **Official Admissions Link:** [${s.admissionsUrl}](${s.admissionsUrl}) *(Tab ${s.admissionsTabId})*\n\n`;
  md += `### Fellowships & Scholarships (Funding)\n`;
  md += `- **Official Funding Link:** [${s.fundingUrl}](${s.fundingUrl}) *(Tab ${s.fundingTabId})*\n\n`;
  s.fellowships.forEach((f, fIdx) => {
    md += `#### ${idx + 1}.${fIdx + 1} ${f.name}\n`;
    md += `- **Eligibility Criteria:** ${f.eligibility}\n`;
    md += `- **Funding Amount:** ${f.amount}\n`;
    md += `- **Specific Opportunity Link:** [${f.url}](${f.url})\n\n`;
  });
  md += `---\n\n`;
});

await writeFile("Top MBA Programs and Fellowships.md", md, "text/markdown");
console.log("Written Top MBA Programs and Fellowships.md");

await tool.artifact({
  action: "write",
  path: "files/",
  filename: "Top_MBA_Programs_and_Fellowships.md",
  content: md,
  mime_type: "text/markdown"
});
console.log("Saved Markdown artifact.");

