// 1. Audit all open tabs using tabs_context
const tabsContext = await tool.tabs_context({ _: "" });
console.log(`Total open tabs: ${tabsContext.pages.length}`);

// Load the 20 schools data
const data = JSON.parse((await read("tmp://mba_data.json")).text);

// Verify each school has its admissions and funding tabs open
const auditResults = [];
let allVerified = true;

for (const s of data) {
  const admTab = tabsContext.pages.find(p => p.tabId === s.admissionsTabId);
  const fundTab = tabsContext.pages.find(p => p.tabId === s.fundingTabId);

  const admOk = admTab != null;
  const fundOk = fundTab != null;

  if (!admOk || !fundOk) allVerified = false;

  auditResults.push({
    school: s.school,
    admissionsTabId: s.admissionsTabId,
    admissionsTabTitle: admTab ? admTab.title : "MISSING",
    admissionsTabUrl: admTab ? admTab.url : "MISSING",
    admissionsOk: admOk,
    fundingTabId: s.fundingTabId,
    fundingTabTitle: fundTab ? fundTab.title : "MISSING",
    fundingTabUrl: fundTab ? fundTab.url : "MISSING",
    fundingOk: fundOk
  });
}

console.log("Audit complete. All tabs verified:", allVerified);
console.log("Sample audit results (first 5):", auditResults.slice(0, 5));

// Update TODO.md
const todoPath = "tmp://sessions/channel%3Apanel%3Ad2bf70d0-e206-4913-a0fc-35d57810de57/TODO.md";
